-- Eight substantial Prophetic Medicine reference entries with separate evidence bibliography.
-- These are marked as editorial drafts requiring independent scholarly/clinical review.
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('honey','honey','Honey','العسل','A Quranic reference to healing and the discipline of evidence','prophetic_medicine','ingredient','Quran 16:69 refers to a drink emerging from bees and associates it with healing. The passage belongs in its wider account of creation and reflection. Different kinds of honey, clinical preparations, and household use cannot be assumed equivalent.','A bee-produced food described in the Quran, not a single standardized pharmaceutical formulation.','Honey, ʿasal, honeybee products','Source-linked original editorial prose; qualified scholarly or clinical review pending.','editorial_draft','published','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-s1','honey','The substance and its identity','overview','Honey is produced by bees from nectar and related plant sources. Its composition, origin, storage and processing can vary. An encyclopedic entry should distinguish ordinary culinary honey from sterile, medically prepared honey used under health-care protocols. The Arabic term al-ʿasal is common in food discourse, but Quran 16:69 is part of a passage describing the bee and what emerges from it. Those contextual distinctions matter whenever a product seller tries to transfer a scriptural phrase into a claim for an individual product.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-s2','honey','The Quranic passage','scripture','Surah al-Naḥl 16:68–69 describes the bee receiving guidance, following pathways and producing a drink of varying colours. The passage mentions healing and presents this as a sign for those who reflect. It does not specify a single recipe, concentration, dose, or universal treatment regimen. A responsible interpretation begins with the full verse, not with a short slogan placed on a retail label. Translation and tafsir require their own attributed review.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-s3','honey','What the reference does and does not establish','interpretation','A Quranic reference is a religious primary source; it is not itself a randomized clinical trial. The verse should be presented faithfully without claiming that any jar of honey cures any chosen disease. The existence of a healing reference does not remove the need to distinguish indications, preparation types, benefits, harms, quality assurance or conventional treatment. Commercial product provenance is a separate, later verification question.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-s4','honey','Contemporary research and safety','science','Research into honey differs by use and formulation. Wound-care products used by clinicians must not be conflated with pantry honey placed on injuries. Evidence concerning cough or other symptoms must be evaluated at the level of specific studies and patient groups rather than generalized from the verse. This record does not assign a clinical efficacy grade. Any future evidence statement should cite a named review, publication date, population, intervention and limitations.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-s5','honey','Practical cautions','safety','Honey must not be given to infants under twelve months because of infant botulism risk. People with allergies or conditions requiring particular dietary management may need individualized advice. Honey is food, not an appropriate replacement for urgent assessment of poisoning, infection or serious symptoms. No commercial listing on Quranically should imply a medical endorsement.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('honey-r1','honey','quran','The Quran — Surah al-Naḥl','16:68–69','https://quran.com/16/69','Read the full passage in its creation-and-reflection context.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('honey-r2','honey','clinical','US Centers for Disease Control and Prevention','Infant botulism prevention','https://www.cdc.gov/botulism/prevention/index.html','Official guidance on honey avoidance in babies under one year.','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('honey-r3','honey','reference','Quranic Arabic Corpus','16:69 parallel translations','https://corpus.quran.com/translation.jsp?chapter=16&verse=69','Translation comparison is not a substitute for tafsir.','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('black-seed','black-seed','Black Seed','الحبة السوداء','Nigella sativa between transmission, botany and modern research','prophetic_medicine','ingredient','Sahih al-Bukhari 5688 transmits a statement on black seed and healing. Understanding that narration, identifying the correct botanical material, and evaluating clinical claims are three separate tasks.','Nigella sativa seed, often sold as a food ingredient or in concentrated oil/extract form.','Black cumin, kalonji, ḥabbah sawdāʾ, Nigella sativa','Source-linked original editorial prose; qualified scholarly or clinical review pending.','editorial_draft','published','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('black-seed-s1','black-seed','Botanical identification','overview','The term black seed is commonly associated with Nigella sativa, a flowering plant whose dark seeds are used as a culinary ingredient. Traders may market different products as black cumin, black caraway or black seed. The encyclopedia therefore records scientific identity, common names and product form rather than treating marketplace labels as interchangeable. Whole seed, culinary oil, capsule and concentrated extract can differ substantially in composition and exposure.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('black-seed-s2','black-seed','The recorded Prophetic narration','transmission','A narration transmitted by Abu Hurayrah appears in Sahih al-Bukhari 5688, in the Book of Medicine. It speaks of healing in black seed while excepting death. The wording and its religious interpretation deserve accurate treatment in context. The hadith''s placement in a recognized collection is a fact about transmission; it does not automatically establish that a particular retail preparation safely treats all medically defined conditions.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('black-seed-s3','black-seed','Questions of interpretation','interpretation','A serious reference work should separate three questions: what exactly is reported, how scholars have understood its general wording, and which contemporary claims can be supported by methodologically sound research. The first two require competent Islamic scholarship. The third requires clinical appraisal by condition, study design, dose, formulation, harms and comparison group. The current entry records the source and these distinctions without announcing a universal medical conclusion.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('black-seed-s4','black-seed','Evidence landscape','science','Published investigations of Nigella sativa and its constituents cover multiple proposed mechanisms and conditions, but the quality and applicability of those investigations cannot be inferred from their number. Laboratory effects, animal findings, small trials and well-conducted clinical evidence are different levels of support. This encyclopedia does not award a therapeutic effectiveness label until specific research reviews are identified, appraised and independently checked.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('black-seed-s5','black-seed','Safety and marketplace identity','safety','Concentrated oils and supplements require more caution than ordinary food use, particularly where medication interactions, pregnancy or chronic illness may matter. Products sold online should be assessed for botanical identity, ingredients, labeling, region and applicable regulation. Quranically will not describe a purchase as fulfilling a Prophetic cure, nor suggest replacing medical care with black seed.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('black-seed-r1','black-seed','hadith','Sahih al-Bukhari — Book of Medicine','5688','https://sunnah.com/bukhari:5688','Primary narration anchor; translation wording and scholarly implications require attribution.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('black-seed-r2','black-seed','reference','Sunnah.com — Book 76, Medicine','Chapter concerning Nigella seeds','https://sunnah.com/bukhari/76','Read neighboring narrations for broader context.','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('black-seed-r3','black-seed','clinical','WHO Traditional Medicine strategy','2025–2034 evidence and safety framework','https://www.who.int/teams/integrated-health-services/traditional-complementary-and-integrative-medicine/global-strategies','Methodological framework, not condition-specific Nigella trial evidence.','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('talbina','talbina','Talbina','التلبينة','Barley nourishment and the narrated consolation of grief','prophetic_medicine','ingredient','Aisha''s report in Sahih al-Bukhari 5689 connects talbina with care during illness and grief. Its role is best understood as a narrated nourishing preparation, not a modern psychiatric prescription.','A traditional barley-based preparation; ingredient variations should be identified rather than assumed.','Talbina, barley porridge','Source-linked original editorial prose; qualified scholarly or clinical review pending.','editorial_draft','published','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('talbina-s1','talbina','What talbina is','overview','Talbina is a barley-derived preparation traditionally cooked into a soft porridge or gruel. Contemporary recipes may vary in the grain used, preparation, toppings and added sweeteners. The name of a food does not prove that two commercial mixes have the same ingredients. Entries and product listings should specify barley content and disclose additions. In this encyclopedia it is classified as food, not as a drug.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('talbina-s2','talbina','Aisha''s transmitted account','transmission','Sahih al-Bukhari 5689 narrates from ʿUrwah that Aisha recommended talbina to a person who was sick or mourning. The narration recounts words about comfort to the heart and alleviation of some sadness. The report''s social setting—food offered in conditions of physical and emotional difficulty—is crucial to its interpretation. Quranically should not detach the phrase from its narrator, collection or context.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('talbina-s3','talbina','Food, consolation and faith','interpretation','Care around illness and bereavement often includes presence, nourishment and human support. The narration provides a meaningful lens through which Muslim readers can reflect on these practices. Yet the report should not be recast as a measurable promise that consuming a particular mix will cure a depressive disorder. Religious counsel and mental-health treatment can coexist. This article links naturally to the encyclopedia''s entries on grief, patience and wellbeing.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('talbina-s4','talbina','What modern evidence would require','science','The nutrition of a barley-based dish can be discussed through established food science, but ingredients, serving size and individual health needs matter. An evidence claim about talbina for depression, anxiety or another diagnosed condition would require suitably controlled human studies, credible outcome measures and independent appraisal. No such clinical conclusion is asserted in this entry.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('talbina-s5','talbina','Dietary and mental-health cautions','safety','Barley contains gluten and is unsuitable for people with coeliac disease or relevant allergy. A commercial food prepared with milk or nuts may introduce other allergens. Persistent distress, suicidal thoughts or serious deterioration require timely professional help. A traditional comfort food should not delay needed care.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('talbina-r1','talbina','hadith','Sahih al-Bukhari — Book of Medicine','5689','https://sunnah.com/bukhari:5689','Aisha''s report regarding talbina for sickness and grief.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('talbina-r2','talbina','hadith','Sahih al-Bukhari — related report','5690','https://sunnah.com/bukhari:5690','Additional talbina narration; consult wording in context.','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('ajwa-dates','ajwa-dates','Ajwa Dates','العجوة','A named variety, a transmitted report, and the limits of retail claims','prophetic_medicine','ingredient','Sahih al-Bukhari 5445 preserves a report about seven Ajwa dates in the morning. Its religious meaning should not be converted into an unverified claim that retail dates prevent poisoning or replace emergency medicine.','A named date cultivar associated with the Madinah region; varietal authenticity is a separate commercial verification.','Ajwa, ʿajwah, Madinah dates','Source-linked original editorial prose; qualified scholarly or clinical review pending.','editorial_draft','published','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ajwa-dates-s1','ajwa-dates','Identity and provenance','overview','Ajwa is a named type of date, not a synonym for all dates sold as dark or premium. Seller labeling and varietal claims require independent substantiation, especially in international commerce. The historical association with Madinah is relevant to provenance, but a city name alone does not authenticate a retail batch. Proper coverage would record cultivar, origin claim, traceability and ingredient integrity without granting religious authority to a seller.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ajwa-dates-s2','ajwa-dates','The authentic narration','transmission','Sahih al-Bukhari 5445 reports from Saʿd a narration involving seven Ajwa dates eaten in the morning, poison and magic. The text should be studied with its complete wording and scholarly explanation. This encyclopedia records the report''s bibliographic location but does not supply an individual ruling or guarantee that following a commercial serving suggestion offers immunity to harm.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ajwa-dates-s3','ajwa-dates','Reading the wording carefully','interpretation','A report may have a recognized authenticity status while questions about its context, scope and application remain for scholars. Treating it as an invitation to ignore poison exposure would be an unsafe distortion. Quranically distinguishes transmitted religious claims from clinical prevention claims and from the marketing of packaged dates. The latter are subject to ordinary consumer evidence and labeling standards.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ajwa-dates-s4','ajwa-dates','Food and nutritional context','science','Dates are a food with carbohydrates, fibre and other constituents. Their nutritional relevance varies with quantity and individual dietary circumstances; nutrition is not a substitute for clinical toxicology or emergency medicine. Comparative health claims between different date cultivars would require specific laboratory and clinical support, not heritage narratives alone.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ajwa-dates-s5','ajwa-dates','Essential safety boundary','safety','If poisoning is suspected, seek emergency medical help immediately. Ajwa is not an antidote, poison-control service or substitute for urgent treatment. People managing diabetes or other conditions affecting dietary carbohydrate intake should make choices appropriate to their own care. Seller offers, if introduced, would be about verified food identity, not immunity or cure.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('ajwa-dates-r1','ajwa-dates','hadith','Sahih al-Bukhari — Book of Foods','5445','https://sunnah.com/bukhari:5445','Ajwa narration; consult full chain, context and original wording.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('ajwa-dates-r2','ajwa-dates','reference','Sahih al-Bukhari — related chapter','Book 70, Ajwa','https://sunnah.com/bukhari/70','Context of the report within the food chapter.','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('olive','olive','The Olive and Its Oil','الزيتون','A Quranic food reference, not a universal therapeutic label','prophetic_medicine','ingredient','Quran 23:20 describes a tree that provides oil and food. A careful encyclopedia distinguishes this Quranic reference, broader symbolism and ordinary food use from claims of medical efficacy.','Olive fruit and expressed food oil; grades and preparations may differ.','Olive, zaytūn, Olea europaea, olive oil','Source-linked original editorial prose; qualified scholarly or clinical review pending.','editorial_draft','published','5');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('olive-s1','olive','The olive as a material and food','overview','The olive tree produces fruit commonly eaten or pressed for oil. Food-grade oils differ in processing, freshness, labeling and quality characteristics. These distinctions matter for both historical understanding and any eventual ingredient marketplace. The encyclopedia treats the plant and its food forms as distinct objects from concentrated botanical extracts or cosmetic mixtures.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('olive-s2','olive','Quran 23:20 in context','scripture','Surah al-Muʾminun 23:20 mentions a tree associated with Mount Sinai that yields oil and provision for those who eat. In its passage, the tree appears among examples of creation and sustenance. Readers should consult the whole section and appropriately attributed tafsir before drawing theological or legal conclusions. The verse establishes a textual reference to oil and food; it does not prescribe a treatment for a named illness.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('olive-s3','olive','Interpretation and symbolism','interpretation','Islamic texts may discuss plants as provision, imagery or signs. Those literary and theological functions should not be collapsed into a single ''cure'' category. Quranically separates what the verse says from later dietary traditions, popular claims and clinical research. A rigorous article should make clear where its source ends and the editor''s explanation begins.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('olive-s4','olive','Health and nutrition questions','science','Olive oil is a widely used food. Health discussions require specific outcomes, comparisons, overall dietary context and evidence quality. Findings about dietary patterns cannot automatically be transferred to a branded oil, and laboratory findings are not a treatment instruction. This record does not claim that olive oil cures a particular disease.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('olive-s5','olive','Safe use and commercial accuracy','safety','Use products appropriate to their stated purpose. Foods, skin products and essential or concentrated extracts should not be treated as interchangeable. Allergies and individual circumstances may matter. Any future seller listing should verify identity, quality representation and destination-country requirements without linking a product to unsupported therapeutic claims.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('olive-r1','olive','quran','The Quran — Surah al-Muʾminun','23:20','https://quran.com/23/20','Tree yielding oil and food.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('olive-r2','olive','reference','Quranic Arabic Corpus','23:20 comparative translations','https://corpus.quran.com/translation.jsp?chapter=23&verse=20','Parallel renderings for editorial comparison.','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('miswak','miswak','Miswak and Siwak','السواك','Prophetic oral cleanliness and modern dental practice','prophetic_medicine','practice','The Prophetic tradition concerning siwak provides a source for Muslim practice around oral hygiene. Its practical relevance should be considered alongside hygiene, material identity and modern dentistry.','Traditional tooth-cleaning implement; several woods and species are marketed under similar names.','Siwak, miswak, tooth-cleaning stick, Salvadora persica','Source-linked original editorial prose; qualified scholarly or clinical review pending.','editorial_draft','published','6');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('miswak-s1','miswak','Terminology and materials','overview','Siwak describes the act or implement used for tooth cleaning, while miswak is commonly used for the twig or stick. Products can be derived from different plants; Salvadora persica is prominent but must not be assumed without accurate seller identification. The material''s cleanliness, storage and handling are central to responsible use.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('miswak-s2','miswak','Narration and devotional context','transmission','Sahih al-Bukhari 887 records a Prophetic statement about recommending the siwak with prayer were it not to cause hardship. The report locates oral cleaning close to worship and daily personal discipline. The actual wording, grading and scope should be studied in full rather than used as a promotional label for an arbitrary toothbrush or twig.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('miswak-s3','miswak','Interpretive distinctions','interpretation','Encouragement of siwak does not prescribe a specific commercial brand, nor does it prove that all marketed sticks provide equal dental outcomes. Readers may pursue the Prophetic practice while remaining attentive to evidence-based oral hygiene. The editorial question is what the narration establishes as religious teaching; the clinical question is how a particular cleaning technique compares with modern standards.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('miswak-s4','miswak','Modern dental-health context','science','Dental plaque control, gum health and cavity prevention depend on many factors. Research concerning sticks, brushing technique, fluoridated toothpaste and professional care should be evaluated separately. No health claim about an unverified product should follow merely from the presence of siwak in a narration.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('miswak-s5','miswak','Safe hygiene practice','safety','Inappropriate force, contaminated implements or poorly stored material may injure gums or introduce hygiene concerns. Continue necessary dental care and consult a dentist about pain, bleeding or infection. Seller listings should avoid replacing established treatment with a promise of religiously guaranteed dental protection.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('miswak-r1','miswak','hadith','Sahih al-Bukhari — siwak','887','https://sunnah.com/bukhari:887','Narration regarding siwak and prayer.','pending','1');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('hijama','hijama','Hijama and Cupping','الحجامة','Historical practice, transmitted references and a high-priority safety boundary','prophetic_medicine','practice','Cupping is discussed in Islamic reports and in traditional medicine across cultures. The existence of a Prophetic-era practice must be distinguished from evidence of benefit for contemporary conditions and serious procedural risks.','A family of procedures involving suction; wet cupping pierces the skin and differs from dry cupping.','Hijama, cupping, wet cupping, dry cupping','Source-linked original editorial prose; qualified scholarly or clinical review pending.','editorial_draft','published','7');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-s1','hijama','Defining the practice','overview','Cupping involves creating suction against the skin with a cup or device. Wet cupping may involve incisions or skin puncture and blood loss; dry cupping does not. These are not equivalent procedures, and a reader searching the Arabic term al-hijama should be shown the distinction before any discussion of possible benefits. This is a practice, not an ingredient for delivery by mail.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-s2','hijama','Recorded historical reference','transmission','Sahih al-Bukhari 5696 is among narrations referencing cupping. A source-linked encyclopedia should present the transmission without converting a historical description into universal advice for modern readers. Different narrations and chapters may concern use, remuneration or other circumstances; each must be assessed according to its own chain, wording and scholarly commentary.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-s3','hijama','What the modern evidence says','science','The US National Center for Complementary and Integrative Health notes that available studies of cupping are often low quality. It reports possible pain relief findings but judges the evidence weak and insufficient for many other conditions. These cautions are specific, not a blanket approval or disapproval of every historical narrative. Clinical conclusions should be updated as reviews improve.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-s4','hijama','Infection, injury and contraindications','safety','Cupping may cause discolouration, burns, scars or infections. Wet cupping introduces bleeding and blood-exposure concerns, and contaminated reused equipment can transmit bloodborne infections. Repeated wet cupping can also cause anaemia. Quranically must never suggest a self-performed invasive procedure, sell a home bloodletting kit or certify an unverified practitioner.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-s5','hijama','Faithful representation of the tradition','interpretation','A responsible presentation honors the authenticity question and the historical setting while refusing to erase modern safety obligations. Readers seeking individual treatment advice should consult licensed health professionals. This article has no ingredient marketplace module; future practitioner directories would require a separate regulatory and clinical eligibility framework.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('hijama-r1','hijama','hadith','Sahih al-Bukhari — Book of Medicine','5696','https://sunnah.com/bukhari:5696','A cupping-related narration; context should be checked by a qualified scholar.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('hijama-r2','hijama','clinical','NIH NCCIH — Cupping','Benefits, evidence quality and safety','https://www.nccih.nih.gov/health/cupping','Authoritative description of evidence limitations and procedure-related harms.','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('ruqyah','ruqyah','Ruqyah','الرقية','Recitation, supplication and safeguarding against exploitation','prophetic_medicine','devotion','Reports concerning ruqyah appear in authenticated hadith literature. Understanding its permissible forms requires competent scholarly teaching; it must never be advertised as permission to delay emergency treatment.','A devotional practice of recitation and supplication, not an ingredient or medical device.','Ruqya, ruqyah sharʿiyyah, recitation for protection','Source-linked original editorial prose; qualified scholarly or clinical review pending.','editorial_draft','published','8');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ruqyah-s1','ruqyah','What is being described','overview','Ruqyah is a term used for recitation and supplication associated with seeking protection or wellbeing. It differs categorically from buying an ingredient or undergoing a physical procedure. The encyclopedia should state that difference before drawing connections to health, because commercialized ''healing products'' can distort religious language.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ruqyah-s2','ruqyah','The recorded narration','transmission','Sahih al-Bukhari 5736 includes a narration involving the recitation of Al-Fatiha in a ruqyah context. The original source and surrounding details matter, including why and how the recitation was recognized. Quranically provides a bibliographic doorway; comprehensive legal conditions and creed-related questions require attribution to qualified scholarship.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ruqyah-s3','ruqyah','Religious and ethical boundaries','interpretation','Practices claiming occult certainty, guaranteed cures or exclusive access to divine intervention should be treated cautiously. The encyclopedia must separate the source tradition from later commercial claims and avoid treating devotional acts as substitutes for professional health services. A religious account does not entitle a website to diagnose a person''s condition.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ruqyah-s4','ruqyah','Healthcare remains essential','safety','Snakebite, poisoning, severe mental-health symptoms, seizures and acute illness require urgent assessment and appropriate medical care. Ruqyah may be part of personal devotion alongside care but must not prevent treatment. Do not send a distressed person to unverified paid healers or suggest abandoning prescribed medicine.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ruqyah-s5','ruqyah','Why there is no seller listing','methodology','No product is necessary to make this a commerce category. Quranically will not monetize vulnerability through paid guaranteed-ruqyah offers. Its role is to connect responsible reading to identifiable religious sources, explain limitations and keep the user''s autonomy intact.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('ruqyah-r1','ruqyah','hadith','Sahih al-Bukhari — Book of Medicine','5736','https://sunnah.com/bukhari:5736','Ruqyah involving Surah Al-Fatiha; review full context.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('ruqyah-r2','ruqyah','quran','The Quran — Al-Fatiha','1:1–7','https://quran.com/1','The chapter associated with the narration.','pending','2');
